use std::path::Path;

fn main() {
    // tauri-build checks that every bundle resource exists. The third-party
    // notices are generated by `npm run notices` (Tauri's beforeBuildCommand)
    // before a bundle; a plain `cargo build` or `cargo test` gets a stub.
    let notices = Path::new("notices/THIRD_PARTY_NOTICES.txt");
    if !notices.exists() {
        std::fs::create_dir_all("notices").expect("create notices/");
        std::fs::write(notices, "Third-party notices are generated by `npm run notices` for a bundle.\n")
            .expect("write the notices stub");
    }
    tauri_build::build()
}
